.btn--link {
  min-block-size: 1.5rem; padding: 0 var(--s1); border: 0; background: none;
  color: var(--accent); font-weight: 500; text-decoration: underline; text-underline-offset: 0.2em;
}
.btn--link:active { background: var(--accent-bg); }
.btn[aria-disabled="true"] { cursor: progress; opacity: 0.85; }
@media (hover: hover) {
  .btn:hover { border-color: var(--ink); }
  .btn--primary:hover { background: oklch(0.43 0.085 170); border-color: oklch(0.43 0.085 170); }
  .btn--danger:hover { background: oklch(0.47 0.16 27); border-color: oklch(0.47 0.16 27); }
  .btn--danger-quiet:hover { background: var(--danger-bg); border-color: var(--danger); }
  .btn--link:hover { text-decoration-thickness: 2px; border: 0; }
}

/* ---------- Fields ---------- */

.field { display: grid; gap: var(--s1); }
.field + .field, .row + .field, .field + .row { margin-block-start: var(--s4); }
.row { display: grid; gap: var(--s4); }
@media (min-width: 30rem) { .row { grid-template-columns: 1fr 1fr; } }

label, .label { font-weight: 600; }
.optional { font-weight: 400; color: var(--muted); }
.hint { color: var(--muted); font-size: 0.9375rem; }

input:not([type="checkbox"]), select {
  inline-size: 100%; min-block-size: 2.75rem;
  padding: var(--s2) var(--s3);
  font: inherit; font-size: 1rem; /* >=16px: no iOS zoom on focus */
  color: var(--ink); background: var(--surface);
  border: 1px solid var(--field); border-radius: var(--r-sm);
}
input:focus-visible, select:focus-visible { outline-offset: 0; border-color: var(--accent); }
input[readonly] { background: var(--bg); border-style: dashed; }
select:disabled, input:disabled { color: var(--ink); opacity: 1; background: var(--bg); }
input[aria-invalid="true"], select[aria-invalid="true"] { border: 2px solid var(--danger); }

.field-error {
  display: flex; gap: var(--s2); align-items: baseline;
  color: var(--danger); font-weight: 600; font-size: 0.9375rem;
}
.field-error::before {
  content: "!"; flex: none; display: inline-grid; place-items: center;
  inline-size: 1.125rem; block-size: 1.125rem; border-radius: 50%;
  background: var(--danger); color: #fff; font-size: 0.75rem; transform: translateY(0.1em);
}
.field-error[hidden] { display: none; }

.check { display: flex; gap: var(--s3); align-items: flex-start; min-block-size: 1.75rem; }
.check + .check { margin-block-start: var(--s3); }
.check input { inline-size: 1.25rem; block-size: 1.25rem; margin: 0.15rem 0 0; accent-color: var(--accent); flex: none; }
.check label { font-weight: 400; }

/* ---------- The tally: one pill for "things that need you" ---------- */

.tally {
  display: inline-flex; align-items: center;
  padding: 0.0625rem var(--s2); border-radius: 999px;
  font-size: 0.875rem; font-weight: 600; line-height: 1.5; white-space: nowrap;
  font-variant-numeric: tabular-nums; vertical-align: 0.1em;
}
.tally--error { background: var(--danger); color: #fff; }
.tally--change { background: var(--accent-bg); color: var(--accent); box-shadow: inset 0 0 0 1px var(--accent); }
.tally[hidden] { display: none; }

/* ---------- Error summary and banners ---------- */

.summary {
  padding: var(--s4) var(--s5); margin-block-end: var(--s6);
  background: var(--danger-bg); border: 2px solid var(--danger); border-radius: var(--r-md);
}
.summary h2 { display: flex; flex-wrap: wrap; align-items: center; gap: var(--s2); font-size: 1.0625rem; }
.summary ul { margin: var(--s3) 0 0; padding-inline-start: var(--s5); }
.summary li + li { margin-block-start: var(--s1); }
.summary a { color: var(--danger); font-weight: 600; }
.summary:focus-visible { outline-offset: 3px; }

.notice {
  padding: var(--s3) var(--s4); margin-block-end: var(--s5);
  border: 1px solid var(--field); border-radius: var(--r-md); background: var(--surface);
}
.notice--ok { border-color: var(--accent); background: var(--accent-bg); }
.notice--error { border-color: var(--danger); background: var(--danger-bg); }
.notice[hidden] { display: none; }

/* ---------- Sign in ---------- */

.auth { min-block-size: 100dvh; display: grid; place-items: start center; padding: var(--s7) var(--s4) var(--s6); }
.auth__inner { inline-size: min(100%, 24rem); }
.auth .wordmark { display: inline-block; margin-block-end: var(--s6); }
.auth h1 { margin-block-end: var(--s5); }
.auth .panel { background: var(--surface); border: 1px solid var(--rule); border-radius: var(--r-md); padding: var(--s5); }
.auth .btn--primary { inline-size: 100%; margin-block-start: var(--s5); }
.label-row { display: flex; justify-content: space-between; align-items: baseline; gap: var(--s3); flex-wrap: wrap; }
.password { position: relative; }
.password input { padding-inline-end: 4.5rem; }
.password .btn--link { position: absolute; inset-inline-end: var(--s2); inset-block-start: 50%; transform: translateY(-50%); }

/* ---------- Settings layout ---------- */

.page { padding: var(--s6) var(--s5) 0; }
.page-head {
  display: flex; align-items: center; justify-content: space-between; gap: var(--s4);
  max-inline-size: 40rem; margin-block-end: var(--s5);
}
.layout { display: grid; grid-template-columns: minmax(0, 40rem); gap: var(--s6); align-items: start; }
.layout > .main { grid-column: 1; grid-row: 2; min-inline-size: 0; }
.help { grid-column: 1; grid-row: 1; }
@media (min-width: 60rem) {
  .layout.help-open { grid-template-columns: minmax(0, 40rem) 20rem; }
  .layout.help-open .page-head { max-inline-size: none; }
  .help { grid-column: 2; grid-row: 1; position: sticky; inset-block-start: var(--s4);
          max-block-size: calc(100dvh - 2rem); overflow: auto; }
  .layout > .main { grid-row: 1; }
}

.help {
  background: var(--surface); border: 1px solid var(--rule); border-radius: var(--r-md);
  padding: var(--s4) var(--s5) var(--s5);
}
.help[hidden] { display: none; }
.help__head { display: flex; justify-content: space-between; align-items: center; gap: var(--s3); margin-block-end: var(--s3); }
.help section { padding: var(--s3); margin-inline: calc(-1 * var(--s3)); border-radius: var(--r-sm); transition: background-color 150ms ease-out; }
.help section.is-current { background: var(--accent-bg); }
.help h3 { font-size: 1rem; margin-block-end: var(--s1); }
.help p { font-size: 0.9375rem; color: var(--muted); }
.help .is-current p { color: var(--ink); }

fieldset { margin: 0; padding: 0; border: 0; min-inline-size: 0; }
fieldset + fieldset { margin-block-start: var(--s6); padding-block-start: var(--s5); border-block-start: 1px solid var(--rule); }
legend {
  display: flex; flex-wrap: wrap; align-items: center; gap: var(--s2);
  padding: 0; margin-block-end: var(--s4);
  font-size: 1.2rem; font-weight: 650;
}
.legend-hint { margin-block: calc(-1 * var(--s3)) var(--s4); }

.savebar {
  position: sticky; inset-block-end: 0; z-index: var(--z-sticky);
  display: flex; align-items: center; justify-content: space-between; flex-wrap: wrap; gap: var(--s3);
  min-block-size: var(--bar-h);
  margin-block-start: var(--s6); padding: var(--s3) 0;
  background: var(--bg); border-block-start: 1px solid var(--field);
}
.savebar__status { display: flex; align-items: center; gap: var(--s2); color: var(--muted); }
.savebar__actions { display: flex; gap: var(--s3); }
.savebar__actions [data-save] { min-inline-size: 9.5rem; } /* no jump on "Saving..." */
.savebar [hidden] { display: none; }

.danger-zone {
  margin-block: var(--s6) var(--s7); padding: var(--s5);
  border: 1px solid var(--danger); border-radius: var(--r-md); background: var(--surface);
}
.danger-zone h2 { color: var(--danger); margin-block-end: var(--s2); }
.danger-zone p { margin-block-end: var(--s4); max-inline-size: 60ch; }

/* ---------- Delete dialog ---------- */

dialog {
  inline-size: min(100% - 2rem, 30rem); padding: var(--s5);
  border: 1px solid var(--rule); border-radius: var(--r-md);
  background: var(--surface); color: var(--ink);
  box-shadow: 0 1rem 3rem oklch(0.2 0.02 170 / 0.25);
}
dialog::backdrop { background: oklch(0.2 0.02 170 / 0.55); }
dialog h2 { margin-block-end: var(--s3); }
dialog p + p, dialog ul { margin-block-start: var(--s3); }
dialog ul { padding-inline-start: var(--s5); margin-block-end: 0; }
dialog .field { margin-block-start: var(--s5); }
.dialog-actions { display: flex; justify-content: flex-end; flex-wrap: wrap; gap: var(--s3); margin-block-start: var(--s5); }
.confirm-name { overflow-wrap: anywhere; }

