// Shared form validation for signin.html and settings.html.
// Rules live in the markup (required, type, pattern, maxlength); messages live in
// data-missing / data-invalid on each control. Errors show below the field and in
// a GOV.UK-style summary at the top of the form.

function messageFor(el) {
  const v = el.validity;
  if (v.valid) return '';
  if (v.customError) return el.validationMessage; // set by the (simulated) server
  if (v.valueMissing) return el.dataset.missing;
  return el.dataset.invalid || el.validationMessage;
}

function showFieldError(el, msg) {
  const out = document.getElementById(el.id + '-error');
  out.textContent = msg;
  out.hidden = !msg;
  if (msg) el.setAttribute('aria-invalid', 'true');
  else el.removeAttribute('aria-invalid');
}

function controlsOf(form) {
  return [...form.elements].filter(el => el.willValidate && document.getElementById(el.id + '-error'));
}

// Validate every control, paint inline errors, fill the summary, update legend tallies.
// Returns the number of errors. Focus moves to the summary when there are any.
function validateForm(form, summary) {
  const errors = controlsOf(form).map(el => [el, messageFor(el)]);
  errors.forEach(([el, msg]) => showFieldError(el, msg));
  const bad = errors.filter(([, msg]) => msg);

  form.querySelectorAll('fieldset').forEach(fs => {
    const tally = fs.querySelector('legend .tally');
    if (!tally) return;
    const n = bad.filter(([el]) => fs.contains(el)).length;
    tally.textContent = plural(n, 'error');
    tally.hidden = n === 0;
  });

  summary.hidden = bad.length === 0;
  if (!bad.length) return 0;
  summary.querySelector('.tally').textContent = plural(bad.length, 'error');
  const list = summary.querySelector('ul');
  list.replaceChildren(...bad.map(([el, msg]) => {
    const a = Object.assign(document.createElement('a'), { href: '#' + el.id, textContent: msg });
    a.addEventListener('click', e => { e.preventDefault(); el.focus(); });
    const li = document.createElement('li');
    li.append(a);
    return li;
  }));
  summary.focus();
  return bad.length;
}

// Validate on blur once the person has changed a field; clear an error as soon as it's fixed.
function watchFields(form) {
  controlsOf(form).forEach(el => {
    let changed = false;
    const recheck = () => {
      if (el.validity.customError) el.setCustomValidity('');
      showFieldError(el, messageFor(el));
    };
    el.addEventListener('input', () => {
      changed = true;
      if (el.getAttribute('aria-invalid')) {
        if (el.validity.customError) el.setCustomValidity('');
        if (!messageFor(el)) showFieldError(el, '');
      }
    });
    el.addEventListener('change', () => { changed = true; });
    el.addEventListener('blur', () => { if (changed) recheck(); });
  });
}

const pluralRules = new Intl.PluralRules('en');
function plural(n, word) {
  return `${n} ${pluralRules.select(n) === 'one' ? word : word + 's'}`;
}

