input.content:
// settings.html: save bar, help panel, viewer mode, delete dialog.
// The saved state IS the form's defaults (defaultValue / defaultChecked / defaultSelected),
// so "unsaved" is a diff against them and Discard is form.reset().

document.addEventListener('DOMContentLoaded', () => {
  const $ = id => document.getElementById(id);
  const form = $('settings-form');
  const summary = $('summary');
  const status = $('save-status');
  const saveBtn = document.querySelector('[data-save]');
  const discardBtn = $('discard');
  const saveError = $('save-error');
  const nameInput = $('workspace-name');
  let busy = false;
  let leaving = false;

  // ---------- Unsaved changes ----------

  const isChanged = el =>
    el.type === 'checkbox' ? el.checked !== el.defaultChecked
    : el.tagName === 'SELECT' ? [...el.options].some(o => o.selected !== o.defaultSelected)
    : el.value !== el.defaultValue;
  const changedCount = () => [...form.elements].filter(el => el.name && isChanged(el)).length;

  function renderStatus(text) {
    const n = changedCount();
    discardBtn.hidden = n === 0;
    if (n) {
      const pill = Object.assign(document.createElement('span'), {
        className: 'tally tally--change', textContent: plural(n, 'unsaved change'),
      });
      status.replaceChildren(pill);
    } else {
      status.textContent = text || 'No unsaved changes';
    }
  }

  // Debounced so screen readers hear the settled count, not every keystroke.
  let statusTimer;
  form.addEventListener('input', () => { clearTimeout(statusTimer); statusTimer = setTimeout(renderStatus, 400); });
  form.addEventListener('change', () => renderStatus());

  addEventListener('beforeunload', e => { if (!leaving && changedCount()) e.preventDefault(); });

  // ---------- Save ----------

  watchFields(form);

  form.addEventListener('submit', e => {
    e.preventDefault();
    if (busy) return;
    saveError.hidden = true;
    if (validateForm(form, summary)) return;
    if (!navigator.onLine) {
      saveError.textContent = 'Couldn’t save: you’re offline. Your changes are still here. Save again when you’re back online.';
      saveError.hidden = false;
      return;
    }
    setBusy(true);
    // ponytail: simulated server round-trip; swap for fetch('/api/workspace', { method: 'PATCH' }).
    setTimeout(() => {
      setBusy(false);
      const webhook = $('webhook-url');
      const host = privateHost(webhook.value);
      if (host) {
        webhook.setCustomValidity(`Tallyline can’t reach ${host} from the internet. Use a public https URL, or a tunnel for local testing.`);
        validateForm(form, summary);
        return;
      }
      commit();
    }, 700);
  });

  function setBusy(on) {
    busy = on;
    if (on) saveBtn.setAttribute('aria-disabled', 'true');
    else saveBtn.removeAttribute('aria-disabled');
    saveBtn.textContent = on ? 'Saving…' : 'Save changes';
    if (on) status.textContent = 'Saving…';
  }

  function commit() {
    for (const el of form.elements) {
      if (el.type === 'checkbox') el.defaultChecked = el.checked;
      else if (el.tagName === 'SELECT') for (const o of el.options) o.defaultSelected = o.selected;
      else if (el.name) el.defaultValue = el.value;
    }
    const time = new Intl.DateTimeFormat(undefined, { timeStyle: 'short' }).format(new Date());
    renderStatus(`All changes saved at ${time}`);
  }

  discardBtn.addEventListener('click', () => {
    form.reset();
    for (const el of form.elements) {
      if (!el.id || !$(el.id + '-error')) continue;
      el.setCustomValidity('');
      showFieldError(el, '');
    }
    form.querySelectorAll('legend .tally').forEach(t => { t.hidden = true; });
    summary.hidden = true;
    saveError.hidden = true;
    renderStatus('Changes discarded');
    saveBtn.focus(); // Discard hides itself; don't drop focus on <body>
  });

  // ---------- Help panel ----------

  const help = $('help');
  const helpToggle = $('help-toggle');
  function setHelp(open) {
    help.hidden = !open;
    helpToggle.setAttribute('aria-expanded', open);
  }
  helpToggle.addEventListener('click', () => setHelp(help.hidden));
  $('help-close').addEventListener('click', () => { setHelp(false); helpToggle.focus(); });
  help.addEventListener('keydown', e => {
    if (e.key === 'Escape') { setHelp(false); helpToggle.focus(); }
  });
  // Follow the person through the form: highlight the matching help (visual only).
  form.addEventListener('focusin', e => {
    const topic = e.target.closest('fieldset')?.dataset.help;
    help.querySelectorAll('section').forEach(s => s.classList.toggle('is-current', s.dataset.for === topic));
  });

  // ---------- Viewer (read-only) ----------

  if (new URLSearchParams(location.search).get('role') === 'viewer') {
    for (const el of form.elements) {
      if (el.tagName === 'INPUT' && el.type !== 'checkbox') el.readOnly = true;
      else el.disabled = true; // selects and checkboxes have no read-only state
    }
    $('viewer-notice').hidden = false;
    $('savebar').hidden = true;
    $('danger-zone').hidden = true;
  }

  // ---------- Delete workspace ----------

  const dialog = $('delete-dialog');
  const confirmInput = $('confirm-name');
  const confirmBtn = $('delete-confirm');
  const cancelBtn = $('delete-cancel');
  let deleting = false;

  $('delete-open').addEventListener('click', () => {
    // The saved name, not an unsaved edit.
    dialog.querySelectorAll('[data-workspace-name]').forEach(el => { el.textContent = nameInput.defaultValue; });
    confirmInput.value = '';
    showFieldError(confirmInput, '');
    dialog.showModal();
  });
  cancelBtn.addEventListener('click', () => { if (!deleting) dialog.close(); });
  dialog.addEventListener('cancel', e => { if (deleting) e.preventDefault(); }); // Escape mid-delete

  $('delete-form').addEventListener('submit', e => {
    e.preventDefault();
    if (deleting) return;
    const name = nameInput.defaultValue;
    if (confirmInput.value.trim() !== name) {
      showFieldError(confirmInput, `Type ${name} exactly as shown to confirm`);
      confirmInput.focus();
      return;
    }
