// Shared form validation for signin.html and settings.html.
// Rules live in the markup (required, type, pattern, maxlength); messages live in
// data-missing / data-invalid on each control. Errors show below the field and in
// a GOV.UK-style summary at the top of the form.

function messageFor(el) {
  const v = el.validity;
  if (v.valid) return '';
  if (v.customError) return el.validationMessage; // set by the (simulated) server
  if (v.valueMissing) return el.dataset.missing;
  return el.dataset.invalid || el.validationMessage;
}

function showFieldError(el, msg) {
  const out = document.getElementById(el.id + '-error');
  out.textContent = msg;
  out.hidden = !msg;
  if (msg) el.setAttribute('aria-invalid', 'true');
  else el.removeAttribute('aria-invalid');
}

function controlsOf(form) {
  return [...form.elements].filter(el => el.willValidate && document.getElementById(el.id + '-error'));
}

// Validate every control, paint inline errors, fill the summary, update legend tallies.
// Returns the number of errors. Focus moves to the summary when there are any.
function validateForm(form, summary) {
  const errors = controlsOf(form).map(el => [el, messageFor(el)]);
  errors.forEach(([el, msg]) => showFieldError(el, msg));
  const bad = errors.filter(([, msg]) => msg);

  form.querySelectorAll('fieldset').forEach(fs => {
    const tally = fs.querySelector('legend .tally');
    if (!tally) return;
    const n = bad.filter(([el]) => fs.contains(el)).length;
    tally.textContent = plural(n, 'error');
    tally.hidden = n === 0;
  });

  summary.hidden = bad.length === 0;
  if (!bad.length) return 0;
  summary.querySelector('.tally').textContent = plural(bad.length, 'error');
  const list = summary.querySelector('ul');
  list.replaceChildren(...bad.map(([el, msg]) => {
    const a = Object.assign(document.createElement('a'), { href: '#' + el.id, textContent: msg });
    a.addEventListener('click', e => { e.preventDefault(); el.focus(); });
    const li = document.createElement('li');
    li.append(a);
    return li;
  }));
  summary.focus();
  return bad.length;
}

// Validate on blur once the person has changed a field; clear an error as soon as it's fixed.
function watchFields(form) {
  controlsOf(form).forEach(el => {
    let changed = false;
    const recheck = () => {
      if (el.validity.customError) el.setCustomValidity('');
      showFieldError(el, messageFor(el));
    };
    el.addEventListener('input', () => {
      changed = true;
      if (el.getAttribute('aria-invalid')) {
        if (el.validity.customError) el.setCustomValidity('');
        if (!messageFor(el)) showFieldError(el, '');
      }
    });
    el.addEventListener('change', () => { changed = true; });
    el.addEventListener('blur', () => { if (changed) recheck(); });
  });
}

const pluralRules = new Intl.PluralRules('en');
function plural(n, word) {
  return `${n} ${pluralRules.select(n) === 'one' ? word : word + 's'}`;
}

// settings.html: save bar, help panel, viewer mode, delete dialog.
// The saved state IS the form's defaults (defaultValue / defaultChecked / defaultSelected),
// so "unsaved" is a diff against them and Discard is form.reset().

document.addEventListener('DOMContentLoaded', () => {
  const $ = id => document.getElementById(id);
  const form = $('settings-form');
  const summary = $('summary');
  const status = $('save-status');
  const saveBtn = document.querySelector('[data-save]');
  const discardBtn = $('discard');
  const saveError = $('save-error');
  const nameInput = $('workspace-name');
  let busy = false;
  let leaving = false;

  // ---------- Unsaved changes ----------

  const isChanged = el =>
    el.type === 'checkbox' ? el.checked !== el.defaultChecked
    : el.tagName === 'SELECT' ? [...el.options].some(o => o.selected !== o.defaultSelected)
    : el.value !== el.defaultValue;
  const changedCount = () => [...form.elements].filter(el => el.name && isChanged(el)).length;

  function renderStatus(text) {
    const n = changedCount();
    discardBtn.hidden = n === 0;
    if (n) {
      const pill = Object.assign(document.createElement('span'), {
        className: 'tally tally--change', textContent: plural(n, 'unsaved change'),
      });
      status.replaceChildren(pill);
    } else {
      status.textContent = text || 'No unsaved changes';
    }
  }

  // Debounced so screen readers hear the settled count, not every keystroke.
  let statusTimer;
  form.addEventListener('input', () => { clearTimeout(statusTimer); statusTimer = setTimeout(renderStatus, 400); });
  form.addEventListener('change', () => renderStatus());

  addEventListener('beforeunload', e => { if (!leaving && changedCount()) e.preventDefault(); });

  // ---------- Save ----------

  watchFields(form);

  form.addEventListener('submit', e => {
    e.preventDefault();
    if (busy) return;
    saveError.hidden = true;
    if (validateForm(form, summary)) return;
    if (!navigator.onLine) {
      saveError.textContent = 'Couldn’t save: you’re offline. Your changes are still here. Save again when you’re back online.';
      saveError.hidden = false;
      return;
    }
    setBusy(true);
    // ponytail: simulated server round-trip; swap for fetch('/api/workspace', { method: 'PATCH' }).
    setTimeout(() => {
      setBusy(false);
      const webhook = $('webhook-url');
      const host = privateHost(webhook.value);
      if (host) {
        webhook.setCustomValidity(`Tallyline can’t reach ${host} from the internet. Use a public https URL, or a tunnel for local testing.`);
        validateForm(form, summary);
        renderStatus();
        return;
      }
      commit();
    }, 700);
  });

  function setBusy(on) {
    busy = on;
    if (on) saveBtn.setAttribute('aria-disabled', 'true');
    else saveBtn.removeAttribute('aria-disabled');
    saveBtn.textContent = on ? 'Saving…' : 'Save changes';
    if (on) status.textContent = 'Saving…';
  }

  function commit() {
    for (const el of form.elements) {
      if (el.type === 'checkbox') el.defaultChecked = el.checked;
      else if (el.tagName === 'SELECT') for (const o of el.options) o.defaultSelected = o.selected;
      else if (el.name) el.defaultValue = el.value;
    }
    const time = new Intl.DateTimeFormat(undefined, { timeStyle: 'short' }).format(new Date());
    renderStatus(`All changes saved at ${time}`);
  }

  discardBtn.addEventListener('click', () => {
    form.reset();
    for (const el of form.elements) {
      if (!el.id || !$(el.id + '-error')) continue;
      el.setCustomValidity('');
      showFieldError(el, '');
    }
    form.querySelectorAll('legend .tally').forEach(t => { t.hidden = true; });
    summary.hidden = true;
    saveError.hidden = true;
    renderStatus('Changes discarded');
    saveBtn.focus(); // Discard hides itself; don't drop focus on <body>
  });

  // ---------- Help panel ----------

  const help = $('help');
  const helpToggle = $('help-toggle');
  function setHelp(open) {
    help.hidden = !open;
    helpToggle.setAttribute('aria-expanded', open);
  }
  helpToggle.addEventListener('click', () => setHelp(help.hidden));
  $('help-close').addEventListener('click', () => { setHelp(false); helpToggle.focus(); });
  help.addEventListener('keydown', e => {
    if (e.key === 'Escape') { setHelp(false); helpToggle.focus(); }
  });
  // Follow the person through the form: highlight the matching help (visual only).
  form.addEventListener('focusin', e => {
    const topic = e.target.closest('fieldset')?.dataset.help;
    help.querySelectorAll('section').forEach(s => s.classList.toggle('is-current', s.dataset.for === topic));
  });

  // ---------- Viewer (read-only) ----------

  if (new URLSearchParams(location.search).get('role') === 'viewer') {
    for (const el of form.elements) {
      if (el.tagName === 'INPUT' && el.type !== 'checkbox') el.readOnly = true;
      else el.disabled = true; // selects and checkboxes have no read-only state
    }
    $('viewer-notice').hidden = false;
    $('savebar').hidden = true;
    $('danger-zone').hidden = true;
  }

  // ---------- Delete workspace ----------

  const dialog = $('delete-dialog');
  const confirmInput = $('confirm-name');
  const confirmBtn = $('delete-confirm');
  const cancelBtn = $('delete-cancel');
  let deleting = false;

  $('delete-open').addEventListener('click', () => {
    // The saved name, not an unsaved edit.
    dialog.querySelectorAll('[data-workspace-name]').forEach(el => { el.textContent = nameInput.defaultValue; });
    confirmInput.value = '';
    showFieldError(confirmInput, '');
    dialog.showModal();
  });
  cancelBtn.addEventListener('click', () => { if (!deleting) dialog.close(); });
  dialog.addEventListener('cancel', e => { if (deleting) e.preventDefault(); }); // Escape mid-delete

  $('delete-form').addEventListener('submit', e => {
    e.preventDefault();
    if (deleting) return;
    const name = nameInput.defaultValue;
    if (confirmInput.value.trim() !== name) {
      showFieldError(confirmInput, `Type ${name} exactly as shown to confirm`);
      confirmInput.focus();
      return;
    }
    showFieldError(confirmInput, '');
    deleting = true;
    confirmBtn.setAttribute('aria-disabled', 'true');
    cancelBtn.setAttribute('aria-disabled', 'true');
    confirmBtn.textContent = 'Deleting…';
    $('delete-status').textContent = 'Deleting workspace…';
    // ponytail: simulated delete; swap for fetch('/api/workspace', { method: 'DELETE' }).
    setTimeout(() => {
      leaving = true;
      location.href = 'signin.html?deleted=' + encodeURIComponent(name);
    }, 900);
  });
});

// Hosts Tallyline's servers could never reach: loopback, RFC 1918, mDNS.
function privateHost(url) {
  let host;
  try { host = new URL(url).hostname; } catch { return ''; }
  return /^(localhost|127\.|10\.|192\.168\.|172\.(1[6-9]|2\d|3[01])\.|\[::1\]$)|\.(local|internal|localhost)$/.test(host) ? host : '';
}

/* Tallyline: shared styles. Tokens and rationale in DESIGN.md. */

:root {
  color-scheme: light;
  --bg: oklch(0.975 0.005 170);
  --surface: oklch(1 0 0);
  --ink: oklch(0.23 0.014 170);
  --muted: oklch(0.47 0.014 170);
  --field: oklch(0.58 0.012 170);   /* input borders, 4.2:1 on surface */
  --rule: oklch(0.91 0.006 170);    /* group separators only */
  --accent: oklch(0.47 0.09 170);
  --accent-bg: oklch(0.95 0.03 170);
  --danger: oklch(0.51 0.17 27);
  --danger-bg: oklch(0.965 0.018 27);

  --s1: 0.25rem; --s2: 0.5rem; --s3: 0.75rem; --s4: 1rem; --s5: 1.5rem; --s6: 2.5rem; --s7: 4rem;
  --r-sm: 0.25rem; --r-md: 0.5rem;
  --bar-h: 4.5rem;

  --z-sticky: 10;
}

*, *::before, *::after { box-sizing: border-box; }
[hidden] { display: none !important; }

html {
  /* The save bar is sticky at the bottom: keep focused fields clear of it. */
  scroll-padding-block: var(--s4) calc(var(--bar-h) + var(--s4));
}

body {
  margin: 0;
  background: var(--bg);
  color: var(--ink);
  font: 1rem/1.5 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  -webkit-text-size-adjust: 100%;
}

h1, h2, h3 { margin: 0; line-height: 1.25; text-wrap: balance; }
h1 { font-size: 1.728rem; letter-spacing: -0.01em; }
h2 { font-size: 1.2rem; }
p { margin: 0; }

::selection { background: var(--accent-bg); color: var(--ink); }
input, select, textarea { caret-color: var(--accent); }

a { color: var(--accent); text-underline-offset: 0.2em; }
@media (hover: hover) { a:hover { text-decoration-thickness: 2px; } }

:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }

.visually-hidden {
  position: absolute; inline-size: 1px; block-size: 1px; overflow: hidden;
  clip-path: inset(50%); white-space: nowrap;
}

.skip {
  position: absolute; inset-inline-start: var(--s4); inset-block-start: -10rem;
  background: var(--surface); padding: var(--s2) var(--s3); border-radius: var(--r-sm);
}
.skip:focus { inset-block-start: var(--s2); }

/* ---------- Top bar ---------- */

.topbar {
  display: flex; align-items: center; gap: var(--s4);
  padding: var(--s3) var(--s5);
  background: var(--surface);
  border-block-end: 1px solid var(--rule);
}
.wordmark { color: var(--ink); font-weight: 700; font-size: 1.0625rem; text-decoration: none; }

/* ---------- Buttons ---------- */

.btn {
  display: inline-flex; align-items: center; justify-content: center; gap: var(--s2);
  min-block-size: 2.75rem; padding: 0 var(--s4);
  border: 1px solid var(--field); border-radius: var(--r-sm);
  background: var(--surface); color: var(--ink);
  font: inherit; font-weight: 600; cursor: pointer;
  touch-action: manipulation;
  transition: background-color 150ms ease-out, border-color 150ms ease-out;
}
.btn:active { background: var(--rule); }
.btn--primary { background: var(--accent); border-color: var(--accent); color: #fff; }
.btn--primary:active { background: oklch(0.4 0.08 170); }
.btn--danger { background: var(--danger); border-color: var(--danger); color: #fff; }
.btn--danger:active { background: oklch(0.44 0.15 27); }
.btn--danger-quiet { color: var(--danger); border-color: var(--danger); }
.btn--danger-quiet:active { background: var(--danger-bg); }
.btn--link {
  min-block-size: 1.5rem; padding: 0 var(--s1); border: 0; background: none;
  color: var(--accent); font-weight: 500; text-decoration: underline; text-underline-offset: 0.2em;
}
.btn--link:active { background: var(--accent-bg); }
.btn[aria-disabled="true"] { cursor: progress; opacity: 0.85; }
@media (hover: hover) {
  .btn:hover { border-color: var(--ink); }
  .btn--primary:hover { background: oklch(0.43 0.085 170); border-color: oklch(0.43 0.085 170); }
  .btn--danger:hover { background: oklch(0.47 0.16 27); border-color: oklch(0.47 0.16 27); }
  .btn--danger-quiet:hover { background: var(--danger-bg); border-color: var(--danger); }
  .btn--link:hover { text-decoration-thickness: 2px; border: 0; }
}

/* ---------- Fields ---------- */

.field { display: grid; gap: var(--s1); }
.field + .field, .row + .field, .field + .row { margin-block-start: var(--s4); }
.row { display: grid; gap: var(--s4); }
@media (min-width: 30rem) { .row { grid-template-columns: 1fr 1fr; } }

label, .label { font-weight: 600; }
.optional { font-weight: 400; color: var(--muted); }
.hint { color: var(--muted); font-size: 0.9375rem; }

input:not([type="checkbox"]), select {
  inline-size: 100%; min-block-size: 2.75rem;
  padding: var(--s2) var(--s3);
  font: inherit; font-size: 1rem; /* >=16px: no iOS zoom on focus */
  color: var(--ink); background: var(--surface);
  border: 1px solid var(--field); border-radius: var(--r-sm);
}
input:focus-visible, select:focus-visible { outline-offset: 0; border-color: var(--accent); }
input[readonly] { background: var(--bg); border-style: dashed; }
select:disabled, input:disabled { color: var(--ink); opacity: 1; background: var(--bg); }
input[aria-invalid="true"], select[aria-invalid="true"] { border: 2px solid var(--danger); }

.field-error {
  display: flex; gap: var(--s2); align-items: baseline;
  color: var(--danger); font-weight: 600; font-size: 0.9375rem;
}
.field-error::before {
  content: "!"; flex: none; display: inline-grid; place-items: center;
  inline-size: 1.125rem; block-size: 1.125rem; border-radius: 50%;
  background: var(--danger); color: #fff; font-size: 0.75rem; transform: translateY(0.1em);
}

.check { display: flex; gap: var(--s3); align-items: flex-start; min-block-size: 1.75rem; }
.check + .check { margin-block-start: var(--s3); }
.check input { inline-size: 1.25rem; block-size: 1.25rem; margin: 0.15rem 0 0; accent-color: var(--accent); flex: none; }
.check label { font-weight: 400; }

/* ---------- The tally: one pill for "things that need you" ---------- */

.tally {
  display: inline-flex; align-items: center;
  padding: 0.0625rem var(--s2); border-radius: 999px;
  font-size: 0.875rem; font-weight: 600; line-height: 1.5; white-space: nowrap;
  font-variant-numeric: tabular-nums; vertical-align: 0.1em;
}
.tally--error { background: var(--danger); color: #fff; }
.tally--change { background: var(--accent-bg); color: var(--accent); box-shadow: inset 0 0 0 1px var(--accent); }

/* ---------- Error summary and banners ---------- */

.summary {
  padding: var(--s4) var(--s5); margin-block-end: var(--s6);
  background: var(--danger-bg); border: 2px solid var(--danger); border-radius: var(--r-md);
}
.summary h2 { display: flex; flex-wrap: wrap; align-items: center; gap: var(--s2); font-size: 1.0625rem; }
.summary ul { margin: var(--s3) 0 0; padding-inline-start: var(--s5); }
.summary li + li { margin-block-start: var(--s1); }
.summary a { color: var(--danger); font-weight: 600; }
.summary:focus-visible { outline-offset: 3px; }

.notice {
  padding: var(--s3) var(--s4); margin-block-end: var(--s5);
  border: 1px solid var(--field); border-radius: var(--r-md); background: var(--surface);
}
